import collections,json,re,subprocess,sys
lane=sys.argv[1]
def rows(rev):
 text=subprocess.check_output(['git','-C',lane,'show',rev+':corpus/SOURCES.md'],text=True)
 result={}
 for line in text.splitlines():
  if re.match(r'^\|\s*S[0-9]{3}\s*\|',line):
   cells=[x.strip() for x in line.split('|')[1:-1]]
   if len(cells)!=11: raise SystemExit('malformed source row')
   if cells[0] in result: raise SystemExit('duplicate source id')
   result[cells[0]]=cells
 return result
before,after=map(rows,sys.argv[2:4])
def counts(rs): return {'rows':len(rs),'tier':dict(sorted(collections.Counter(r[3] for r in rs.values()).items())),'status':dict(sorted(collections.Counter(r[7] for r in rs.values()).items()))}
print(json.dumps({'before_revision':sys.argv[2],'after_revision':sys.argv[3],'before':counts(before),'after':counts(after),'new_ids':sorted(after.keys()-before.keys()),'older_non_usedby_cells_unchanged':all(after[k][:10]==r[:10] for k,r in before.items()),'older_usedby_changes':[{'id':k,'old':r[10],'new':after[k][10]} for k,r in before.items() if after[k][10]!=r[10]]},indent=2))
